#!/usr/bin/env bash
# shellcheck source-path=SCRIPTDIR
# get-current-deployed-version.sh — Capture the currently deployed version (CH2/RTF/on-prem) for rollback.
#
# GENERATED by tests/parity/extract_inline_bash.py — do not hand-edit (change the Azure source or
# the extractor, then run it with --write). Extracted from the Azure DevOps inline step:
#   source : platforms/azure-devops/mulesoft-pipeline-templates/pipelines/templates/tasks/get-current-deployed-version.yml
#   step   : "Capture Current Deployed Version" (Bash@3 inline)
# The body is that step verbatim, except: ##vso commands -> ci-shim calls, Azure predefined
# variables -> ci-shim normalizers, and $(...) / ${{ parameters.* }} macros -> the MDF_* inputs below.
#
# Inputs (environment):
#   MDF_APP_SUFFIX         <- ${{ parameters.appSuffix }}  [default: (empty)]
#   MDF_ARTIFACT_ID        <- ${{ parameters.artifactId }}  [required]
#   MDF_BEARER_TOKEN       <- ${{ parameters.bearerToken }}  [required]
#   MDF_BG_ID              <- ${{ parameters.bgId }}  [default: $(BG_ID)]
#   MDF_DEPLOYMENT_TARGET  <- ${{ parameters.deploymentTarget }}  [default: ch2]
#   MDF_ENV_ID             <- ${{ parameters.envId }}  [default: $(ENV_ID)]
#   MDF_GROUP_ID           <- ${{ parameters.groupId }}  [default: (empty)]
#   MDF_MULE_ENV           <- ${{ parameters.muleEnv }}  [default: (empty)]
# Outputs: prevVersion (output), prevArtifactId (output), prevGroupId (output), isFirstDeployment (output)

# shellcheck source=lib/ci-shim.sh
source "$(dirname "${BASH_SOURCE[0]}")/lib/ci-shim.sh"

: "${MDF_APP_SUFFIX=}"
: "${MDF_ARTIFACT_ID?MDF_ARTIFACT_ID is required (Azure parameter artifactId)}"
: "${MDF_BEARER_TOKEN?MDF_BEARER_TOKEN is required (Azure parameter bearerToken)}"
: "${MDF_BG_ID=}"
: "${MDF_DEPLOYMENT_TARGET=ch2}"
: "${MDF_ENV_ID=}"
: "${MDF_GROUP_ID=}"
: "${MDF_MULE_ENV=}"

# >>> extracted body
ARTIFACT_ID="${MDF_ARTIFACT_ID}"
DEPLOYMENT_TARGET="${MDF_DEPLOYMENT_TARGET}"
BG_ID="${MDF_BG_ID}"
ENV_ID="${MDF_ENV_ID}"
MULE_ENV="${MDF_MULE_ENV}"
APP_SUFFIX="${MDF_APP_SUFFIX}"
GROUP_ID="${MDF_GROUP_ID}"
MULE_ENV_LOWER=$(echo "$MULE_ENV" | tr '[:upper:]' '[:lower:]')

# Keep app-name resolution in sync with deploy-mule-application.yml.
BASE_APP_NAME="${ARTIFACT_ID#mule-}"
if [[ -n "$APP_SUFFIX" ]]; then
  APP_NAME="${BASE_APP_NAME}${APP_SUFFIX}"
elif [[ -n "$MULE_ENV" && "$MULE_ENV" != "PROD" ]]; then
  APP_NAME="${BASE_APP_NAME}-${MULE_ENV_LOWER}"
else
  APP_NAME="${BASE_APP_NAME}"
fi

echo "[DEBUG] ============================================"
echo "[DEBUG] CAPTURE CURRENT DEPLOYED VERSION"
echo "[DEBUG] ============================================"
echo "[DEBUG] Parameters:"
echo "[DEBUG]   artifactId=$ARTIFACT_ID"
echo "[DEBUG]   deploymentTarget=$DEPLOYMENT_TARGET"
echo "[DEBUG]   bgId=$BG_ID"
echo "[DEBUG]   envId=$ENV_ID"
echo "[DEBUG]   muleEnv=$MULE_ENV"
echo "[DEBUG]   groupId=$GROUP_ID"
echo "[DEBUG]   appSuffix=$APP_SUFFIX"
echo "[DEBUG]   APP_NAME (computed)=$APP_NAME"
echo "[DEBUG] ============================================"

echo "Querying current deployed version for: $APP_NAME"
echo "  Deployment target: $DEPLOYMENT_TARGET"
echo "  Environment: $ENV_ID"

PREV_VERSION=""
PREV_ARTIFACT_ID=""
PREV_GROUP_ID=""
IS_FIRST_DEPLOYMENT="false"

if [[ "$DEPLOYMENT_TARGET" == "ch2" || "$DEPLOYMENT_TARGET" == "rtf" ]]; then
  # Query CloudHub 2 / RTF via Runtime Manager API
  echo "[DEBUG] Querying CH2/RTF deployments API..."
  response=$(curl -s --request GET \
    --url "https://anypoint.mulesoft.com/amc/application-manager/api/v2/organizations/${BG_ID}/environments/${ENV_ID}/deployments" \
    --header "Authorization: Bearer ${MDF_BEARER_TOKEN}" \
    --header "Content-Type: application/json")
  echo "[DEBUG] Deployments API response items count: $(echo "$response" | jq '.items | length' 2>/dev/null || echo 'parse-error')"

  # Find the application by name
  app_info=$(echo "$response" | jq -r --arg name "$APP_NAME" '.items[] | select(.name == $name)')
  echo "[DEBUG] App match for '$APP_NAME': $([ -n "$app_info" ] && echo 'FOUND' || echo 'NOT FOUND')"

  if [[ -z "$app_info" || "$app_info" == "null" ]]; then
    echo "No existing deployment found for '$APP_NAME'. First deployment."
    IS_FIRST_DEPLOYMENT="true"
  else
    # Extract version from the application info
    PREV_ARTIFACT_ID=$(echo "$app_info" | jq -r '.application.artifactId // empty')
    PREV_GROUP_ID=$(echo "$app_info" | jq -r '.application.groupId // empty')
    PREV_VERSION=$(echo "$app_info" | jq -r '.application.version // empty')
    if [[ -z "$PREV_ARTIFACT_ID" ]]; then
      PREV_ARTIFACT_ID="$ARTIFACT_ID"
    fi
    if [[ -z "$PREV_GROUP_ID" ]]; then
      PREV_GROUP_ID="$BG_ID"
    fi

    # Fallback: parse version from artifact reference
    if [[ -z "$PREV_VERSION" ]]; then
      artifact_ref=$(echo "$app_info" | jq -r '.application.ref.artifactId // empty')
      if [[ -n "$artifact_ref" ]]; then
        PREV_VERSION=$(echo "$artifact_ref" | grep -oP '\d+\.\d+\.\d+')
      fi
    fi

    if [[ -z "$PREV_VERSION" ]]; then
      echo "Could not determine previous version. Treating as first deployment."
      IS_FIRST_DEPLOYMENT="true"
    else
      echo "Current deployed version: $PREV_VERSION"
      echo "Current artifact: ${PREV_GROUP_ID}:${PREV_ARTIFACT_ID}:${PREV_VERSION}"
    fi
  fi

elif [[ "$DEPLOYMENT_TARGET" == "onprem" ]]; then
  # Query ARM API for on-prem deployments
  echo "[DEBUG] Querying ARM API for on-prem deployments..."
  response=$(curl -s --request GET \
    --url "https://anypoint.mulesoft.com/hybrid/api/v1/applications" \
    --header "Authorization: Bearer ${MDF_BEARER_TOKEN}" \
    --header "X-ANYPNT-ENV-ID: ${ENV_ID}" \
    --header "X-ANYPNT-ORG-ID: ${BG_ID}")
  echo "[DEBUG] ARM applications count: $(echo "$response" | jq '.data | length' 2>/dev/null || echo 'parse-error')"

  app_info=$(echo "$response" | jq -r --arg name "$APP_NAME" '.data[] | select(.name == $name)')
  echo "[DEBUG] App match for '$APP_NAME' (on-prem): $([ -n "$app_info" ] && echo 'FOUND' || echo 'NOT FOUND')"

  if [[ -z "$app_info" || "$app_info" == "null" ]]; then
    echo "No existing on-prem deployment found for '$APP_NAME'. First deployment."
    IS_FIRST_DEPLOYMENT="true"
  else
    # Parse version from fileName
    file_name=$(echo "$app_info" | jq -r '.artifact.fileName // empty')
    if [[ -n "$file_name" ]]; then
      PREV_VERSION=$(echo "$file_name" | sed -n "s/.*${ARTIFACT_ID}-\(.*\)-mule-application.jar/\1/p")
      PREV_ARTIFACT_ID="$ARTIFACT_ID"
      PREV_GROUP_ID=$(echo "$app_info" | jq -r '.artifact.groupId // .artifact.maven.groupId // .groupId // empty')
      if [[ -z "$PREV_GROUP_ID" ]]; then
        PREV_GROUP_ID="$GROUP_ID"
      fi
    fi

    if [[ -z "$PREV_VERSION" ]]; then
      echo "Could not parse version from artifact. Treating as first deployment."
      IS_FIRST_DEPLOYMENT="true"
    else
      echo "Current deployed version (on-prem): $PREV_VERSION"
    fi
  fi
fi

# Set output variables
ci_set_var prevVersion "$PREV_VERSION"
ci_set_var prevArtifactId "$PREV_ARTIFACT_ID"
ci_set_var prevGroupId "$PREV_GROUP_ID"
ci_set_var isFirstDeployment "$IS_FIRST_DEPLOYMENT"

echo ""
echo "Summary:"
echo "  Previous Version: ${PREV_VERSION:-N/A}"
echo "  Previous ArtifactId: ${PREV_ARTIFACT_ID:-N/A}"
echo "  First Deployment: $IS_FIRST_DEPLOYMENT"
echo "[DEBUG] CAPTURE CURRENT DEPLOYED VERSION COMPLETE"
echo "[DEBUG] Outputs: prevVersion=$PREV_VERSION, prevArtifactId=$PREV_ARTIFACT_ID, prevGroupId=$PREV_GROUP_ID, isFirstDeployment=$IS_FIRST_DEPLOYMENT"
# <<< extracted body
